namespace AI.Contracts.Navigation;

public sealed record AppNavigationTarget(string Id, string Label, string? Section,
    IReadOnlyList<string> Actions, bool? Visible = null, string? Hint = null, string? UiLabel = null,
    string? UiHint = null, bool? Enabled = null, string? State = null, string? Summary = null);

/// <summary>Semantic targets shared by the tool and the UI; selectors and coordinates stay in the client.</summary>
public interface IAppNavigationTargets
{
    IReadOnlyList<AppNavigationTarget> All { get; }
    AppNavigationTarget? Find(string id);
}

