    public AppNavigationTargets()
    {
        const string template = "widgets.chat-usage";
        var widgets = _definitions.Where(target => target.Id != template
            && (target.Id.StartsWith("widgets.chat-", StringComparison.Ordinal) || target.Id == "widgets.app-guide")
            && target.Id.LastIndexOf('.') == "widgets".Length);
        var actions = _definitions.Where(target => target.Id.StartsWith(template + ".", StringComparison.Ordinal));
        All = [.. _definitions, .. widgets.SelectMany(widget => actions.Select(action =>
            action with { Id = widget.Id + action.Id[template.Length..] }))];
    }

    public IReadOnlyList<AppNavigationTarget> All { get; }

    public AppNavigationTarget? Find(string id) => All.FirstOrDefault(target => target.Id == id);
}
